/*
 * A152444  n is included if the largest proper divisor of n that is coprime
 *          to d(n) is a composite, where d(n) is the total number of divisors
 *          of n.
 * https://oeis.org/A152444
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth integer n such that the largest proper divisor
 *            of n that is coprime with d(n), the number of divisors of n, is
 *            composite. The sequence is generated by exhaustive search
 * Range:     u8 n <= 55, u16 n <= 55, u32 n <= 55, u64 n <= 55, u128 n <= 55,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/* Greatest common divisor for 64‑bit unsigned integers. */
static uint64_t gcd64(uint64_t a, uint64_t b)
{
    while (b != 0) {
        uint64_t t = a % b;
        a = b;
        b = t;
    }
    return a;
}

/* Simple primality test for 64‑bit unsigned integers. */
static bool is_prime(uint64_t x)
{
    if (x < 2) return false;
    if (x % 2 == 0) return x == 2;
    if (x % 3 == 0) return x == 3;
    for (uint64_t i = 5; i * i <= x; i += 6) {
        if (x % i == 0 || x % (i + 2) == 0) return false;
    }
    return true;
}

/* Factorise n; pf[] holds distinct prime factors,
   ex[] holds their exponents; returns number of factors. */
static size_t factor_uint64(uint64_t n, uint64_t *pf, int *ex)
{
    size_t cnt = 0;
    if (n == 1) return 0;
    for (uint64_t p = 2; p * p <= n; ++p) {
        if (n % p == 0) {
            int e = 0;
            while (n % p == 0) {
                n /= p;
                ++e;
            }
            pf[cnt] = p;
            ex[cnt] = e;
            ++cnt;
        }
    }
    if (n > 1) {               /* remaining prime factor */
        pf[cnt] = n;
        ex[cnt] = 1;
        ++cnt;
    }
    return cnt;
}

/* Generate all divisors of m from its prime factorisation.
   divs[] must be large enough to hold them; divcnt will contain the
   number of divisors produced. */
static void generate_divisors(uint64_t m,
                              const uint64_t *pf,
                              const int *ex,
                              size_t cnt,
                              uint64_t *divs,
                              size_t *divcnt)
{
    size_t cur = 1;
    divs[0] = 1;
    for (size_t i = 0; i < cnt; ++i) {
        uint64_t p = pf[i];
        int e = ex[i];
        size_t old = cur;
        uint64_t mult = 1;
        for (int k = 1; k <= e; ++k) {
            mult *= p;
            for (size_t j = 0; j < old; ++j) {
                divs[cur++] = divs[j] * mult;
            }
        }
    }
    *divcnt = cur;
}

/* Main sequence function. */
seq_t a(idx_t n)
{
    idx_t found = 0;
    uint64_t m = 0;

    /* Small static buffers that persist between calls. */
    static uint64_t pf[20];
    static int      ex[20];
    static uint64_t divisors[2048];

    while (found < n) {
        ++m;
        if (m <= 1) continue;        /* 1 has no proper divisors */

        /* Factorise m. */
        size_t pfcnt = factor_uint64(m, pf, ex);

        /* Compute d(m). */
        uint64_t d_m = 1;
        for (size_t i = 0; i < pfcnt; ++i) d_m *= (uint64_t)(ex[i] + 1);

        /* Generate all divisors of m. */
        size_t divcnt;
        generate_divisors(m, pf, ex, pfcnt, divisors, &divcnt);

        /* Find largest proper divisor coprime to d_m. */
        uint64_t largest = 0;
        for (size_t i = 0; i < divcnt; ++i) {
            uint64_t d = divisors[i];
            if (d == m) continue;            /* skip m itself */
            if (gcd64(d, d_m) != 1) continue;
            if (d > largest) largest = d;
        }

        /* Property satisfied if largest proper divisor exists and is composite. */
        if (largest > 1 && !is_prime(largest)) {
            ++found;
            if (found == n) return (seq_t)m;
        }
    }
    /* control will never reach here for valid n >= 1 */
    return (seq_t)0;
}
